__NUXT_JSONP__("/feature", (function(a){return {data:[{details:{slug:"en",pageTitle:"5 Reasons People Choose MLI | Mentor Language Institute",pageDescription:"We have helped more than 17,000 students improve their English skills since our opening.",section1:{title:"5 Reasons People Choose MLI",image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fmli-mentor.jpg"},section2:{title:"5 Characteristics of Mentor Language Institute",description:["We have helped \u003Cb\u003Emore than 17,000 students\u003C\u002Fb\u003E improve their English skills since our opening. Why do students choose MLI even though there are so many English schools in Los Angeles? We took a survey of MLI students and their answers are below."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fsurvey.jpg",notes:"Survey period : January to June in 2017 of 342 students"},section3:[{title:"No.1 : Reasonable Price",subtitle:"Great Price! From $209 per week Afternoon classes are 40% off the price of morning classes!",description:["The number 1 reason students choose MLI is affordability.","The longer you attend our school, the cheaper the tuition. If you apply for 1 month (4 weeks), the tuition is $1,220 = \u003Cb\u003E$305 per week\u003C\u002Fb\u003E. This is already reasonable price in LA. But, if you apply for 48 weeks, the tuition is $10,032 = \u003Cspan style=\"color: #ff0000; font-weight: bold;\"\u003E$209 per week.\u003C\u002Fspan\u003E Please compare our rates with other schools."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002FPRICE_CHART_WEB_JAN06.jpg",links:[{icon:a,text:"Details about Tuition",link:"\u002Fprice"}]},{title:"No.2 : Great Location",subtitle:"Westwood & Hollywood : popular areas in Los Angeles",description:["We are located in great, popular areas of Los Angeles, \u003Cb\u003EWestwood\u003C\u002Fb\u003E and \u003Cb\u003EHollywood\u003C\u002Fb\u003E. Students can easily access famous places such as Santa Monica and downtown LA."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fgreat-location.jpg",locations:[{image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fwestwood-campus.jpg",label:"Westwood Campus"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fhollywood-campus.jpg",label:"Hollywood Campus"}],links:[{icon:a,text:"Details about Westwood Campus",link:"\u002Fwestwood"},{icon:a,text:"Details about Hollywood Campus",link:"\u002Fhollywood"}]},{title:"No.3 : Variety of College Preparation Courses",subtitle:"Many students transfer to UCLA and Santa Monica College after studying at MLI.",description:["We offer popular test preparation program such as \u003Cb\u003ETOEFL®, IELTS™.\u003C\u002Fb\u003E Many students transfer to \u003Cb\u003EUCLA, USC\u003C\u002Fb\u003E and \u003Cb\u003ESanta Monica College\u003C\u002Fb\u003E after completing our test preparation program."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fgoing-to-college.jpg",links:[{icon:a,text:"Details about Going to Collage",link:"\u002Fgoing-to-college"}]},{title:"No.4 : Flexible Class Schedule",subtitle:"We offer morning, afternoon and evening classes.",description:["\u003Cb\u003EMLI offers 3 different class schedules.\u003C\u002Fb\u003E Students can choose from morning, afternoon and evening classes."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fclass-schedule.png",notes:"※This is a class schedule for Westwood Campus. If you'd like the Hollywood Campus schedule, please contact us."},{title:"No.5 : Dormitory",subtitle:"Our Partner: US Support Services Inc. offers the opportunity to communicate with students from all over the world at our dormitory.",description:["Our partner: U.S. Support Service Inc. arranges homestay programs and also dormitories. They provide more than 40 rooms at our dormitories located near each campus.  Many students stay at a dormitory if it's their first time in the States."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fdormitory.jpg",links:[{icon:a,text:"Details about Accommodations",link:"\u002Fstay"}]}],dir:"\u002Ffeature",path:"\u002Ffeature\u002Fen",extension:".json",createdAt:"2026-10-22T16:31:29.192Z",updatedAt:"2026-03-24T13:34:16.381Z"}}],fetch:{},mutations:void 0}}("\u002Fimages\u002Ficons\u002Fboxed-arrow.svg")));